# inspect columns and compute conversion rates by group
import pandas as pd
cols = list(df.columns)
result = {}
# try common column names
for gcol in ['group','Group','variant','Variant','cohort','Cohort']:
    if gcol in df.columns:
        group_col = gcol
        break
else:
    group_col = None
for ccol in ['conversions','Conversions','converted','Converted','conversion','Conversion']:
    if ccol in df.columns:
        conv_col = ccol
        break
else:
    conv_col = None
for ucol in ['users','Users','user_count','UserCount','n_users']:
    if ucol in df.columns:
        users_col = ucol
        break
else:
    users_col = None

if group_col is None or conv_col is None or users_col is None:
    raise ValueError(f'Columns not found. columns={cols}, detected={(group_col, conv_col, users_col)}')

rates = df.groupby(group_col, dropna=False).agg({conv_col:'sum', users_col:'sum'})
rates['rate'] = rates[conv_col] / rates[users_col]
best_group = rates['rate'].idxmax()
best_rate = rates.loc[best_group, 'rate']
print({'best_group': best_group, 'best_rate': float(best_rate), 'columns': cols, 'detected': (group_col, conv_col, users_col)})

